import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { likeComment } from "../handlers/likeComment";
import type { ApiError } from "../runtime/client";
import type { LikeCommentRequest } from "../types/LikeCommentRequest";
import type { SpacePartition } from "../types/SpacePartition";
import type { SpacePostCommentTargetEntityType } from "../types/SpacePostCommentTargetEntityType";
import type { SpacePostEntityType } from "../types/SpacePostEntityType";

type Data = Awaited<ReturnType<typeof likeComment>>;
type Vars = { spaceId: SpacePartition; discussionSk: SpacePostEntityType; commentSk: SpacePostCommentTargetEntityType; req: LikeCommentRequest };

export function useLikeComment(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => likeComment(vars.spaceId, vars.discussionSk, vars.commentSk, vars.req),
    ...options,
  });
}
